<?php
session_start();
require_once __DIR__.'/../koneksi.php';require_once __DIR__.'/../includes/auth.php';requireRole(['admin','kasir','bendahara']);
require_once __DIR__.'/../includes/savings_workspace.php';require_once __DIR__.'/../includes/migrated_savings.php';require_once __DIR__.'/../includes/savings_operator.php';require_once __DIR__.'/../includes/history_operator_filter.php';require_once __DIR__.'/../includes/history_class_filter.php';require_once __DIR__.'/../includes/migrated_history.php';require_once __DIR__.'/../includes/pagination.php';
if($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);exit('Gunakan GET.');}
try {
    if(($_GET['view']??'active')!=='active')throw new InvalidArgumentException('Ekspor ini tersedia untuk transaksi aktif.');
    $format=mh_choice($_GET,'format',['xlsx','pdf'],'xlsx');$classes=history_class_filter($koneksi,$_GET);$ops=history_operator_choices($_GET['operator']??null,savings_operator_options($koneksi));
    $start=(string)($_GET['tanggal_awal']??date('Y-m-01'));$end=(string)($_GET['tanggal_akhir']??date('Y-m-d'));
    foreach([$start,$end] as $date)if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date))throw new InvalidArgumentException('Tanggal tidak valid.');
    if($start>$end)[$start,$end]=[$end,$start];
    $query=mh_savings_read_query($koneksi,$_GET,$classes,$ops,$start.' 00:00:00',date('Y-m-d H:i:s',strtotime($end.' +1 day')));
    $total=(int)lf_one($koneksi,'SELECT COUNT(*) n FROM ('.$query['sql'].') z',$query['args'])['n'];$size=page_size_param('per_page',[10,25,50],10);$pages=max(1,(int)ceil($total/$size));$page=min($pages,page_int_param('page'));$sql=$query['sql'].' ORDER BY TANGGAL DESC,jenis,id DESC';
    $result=['page'=>$page,'pages'=>$pages,'total'=>$total,'rows'=>$format==='pdf'?lf_rows($koneksi,$sql.' LIMIT '.$size.' OFFSET '.(($page-1)*$size),$query['args']):[],'read_sql'=>$sql,'read_args'=>$query['args']];
    $headers=['Nama Pemilik','Identitas Sumber / NIS','Unit','Kelas','Tanggal','Masuk','Keluar','Penyesuaian','Jenis Jurnal','Jenis Pemilik'];
    $values=static fn($p)=>[$p['NAMA'],$p['NO_INDUK'],unit_label((int)$p['unit_id']),class_label($p),$p['TANGGAL']?:'Tidak tercatat',$p['nominal'],$p['keluar'],$p['adjustment_delta'],['native'=>'SistemSPP','new'=>'SistemSPP','legacy'=>'Jurnal Legacy','adjustment'=>'Penyesuaian Saldo Migrasi'][$p['origin']]??$p['origin'],$p['student_id']?'Siswa':'Rekening non-siswa'];
    if($format==='pdf'){
        $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');ob_start();
        ?><html lang="id"><meta charset="utf-8"><style>@page{margin:25px}body{font:10px DejaVu Sans}table{border-collapse:collapse;width:100%}th,td{padding:6px;border:1px solid #ccd9d2}th{background:#eaf4ee}h1{font-size:17px}</style><h1>Riwayat Tabungan — <?= $e(unit_label(unit_active_id())) ?></h1><p>Halaman <?= $result['page'] ?> dari <?= $result['pages'] ?> · <?= $result['total'] ?> jurnal sesuai filter. Penyesuaian tidak masuk setoran/penarikan. Excel mencakup seluruh hasil filter.</p><table><tr><?php foreach($headers as $h): ?><th><?= $e($h) ?></th><?php endforeach; ?></tr><?php foreach($result['rows'] as $p): ?><tr><?php foreach($values($p) as $i=>$v): ?><td><?= in_array($i,[5,6,7],true)?$e(number_format((float)$v,2,',','.')):$e($v) ?></td><?php endforeach; ?></tr><?php endforeach; ?></table></html><?php
        $html=ob_get_clean();require_once __DIR__.'/../includes/pdf.php';require_pdf_library();$pdf=new \Dompdf\Dompdf();$pdf->loadHtml($html,'UTF-8');$pdf->setPaper('A4','landscape');$pdf->render();$pdf->stream('riwayat-tabungan-halaman-'.$result['page'].'.pdf',['Attachment'=>false]);exit;
    }
    // Stream XML rows to a private temporary file; no workbook-sized PHP array.
    $sheet=tempnam(sys_get_temp_dir(),'spp-history-');$file=tempnam(sys_get_temp_dir(),'spp-xlsx-');
    try {
        $xml=new XMLWriter();$xml->openUri($sheet);$xml->startDocument('1.0','UTF-8');$xml->startElement('worksheet');$xml->writeAttribute('xmlns','http://schemas.openxmlformats.org/spreadsheetml/2006/main');
        $xml->startElement('sheetViews');$xml->startElement('sheetView');$xml->writeAttribute('workbookViewId','0');$xml->startElement('pane');$xml->writeAttribute('ySplit','1');$xml->writeAttribute('topLeftCell','A2');$xml->writeAttribute('state','frozen');$xml->endElement();$xml->endElement();$xml->endElement();
        $xml->startElement('cols');foreach([28,25,10,22,24,20,20,20,28,23] as $i=>$width){$xml->startElement('col');$xml->writeAttribute('min',(string)($i+1));$xml->writeAttribute('max',(string)($i+1));$xml->writeAttribute('width',(string)$width);$xml->writeAttribute('customWidth','1');$xml->endElement();}$xml->endElement();$xml->startElement('sheetData');
        $write=static function(array $row,int $number,bool $header=false)use($xml){$xml->startElement('row');$xml->writeAttribute('r',(string)$number);foreach($row as $i=>$v){$xml->startElement('c');$xml->writeAttribute('r',chr(65+$i).$number);$xml->writeAttribute('s',$header?'1':(in_array($i,[5,6,7],true)?'2':'0'));if(!$header&&in_array($i,[5,6,7],true)){$xml->writeElement('v',(string)$v);}else{$xml->writeAttribute('t','inlineStr');$xml->startElement('is');$xml->writeElement('t',preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/u','',(string)$v));$xml->endElement();}$xml->endElement();}$xml->endElement();};
        $write($headers,1,true);$s=$koneksi->prepare($result['read_sql']);if($result['read_args'])$s->bind_param(str_repeat('s',count($result['read_args'])),...$result['read_args']);$s->execute();$fields=$s->result_metadata()->fetch_fields();$bound=array_fill(0,count($fields),null);$s->bind_result(...$bound);$number=1;
        while($s->fetch()){$p=[];foreach($fields as $i=>$f)$p[$f->name]=$bound[$i];$write($values($p),++$number);}$s->close();
        $xml->endElement();$xml->startElement('autoFilter');$xml->writeAttribute('ref','A1:J'.$number);$xml->endElement();$xml->endElement();$xml->endDocument();$xml->flush();unset($xml);
        $zip=new ZipArchive();if($zip->open($file,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Tidak dapat menyiapkan Excel.');
        $zip->addFromString('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');
        $zip->addFromString('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
        $zip->addFromString('xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Riwayat Tabungan" sheetId="1" r:id="rId1"/></sheets></workbook>');
        $zip->addFromString('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
        $zip->addFromString('xl/styles.xml','<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF127B46"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"/><xf numFmtId="4" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
        $zip->addFile($sheet,'xl/worksheets/sheet1.xml');$zip->close();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="riwayat-tabungan.xlsx"');header('Cache-Control: private, no-store');readfile($file);
    }finally{if(isset($xml))unset($xml);if(is_file($sheet))unlink($sheet);if(is_file($file))unlink($file);}
}catch(InvalidArgumentException $e){http_response_code(400);echo htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8');}
